variables.targets:
{% set ns = namespace(values={}) %}
{% set eco = states('input_number.eco_temp_default') | float(default=none) %}
{% set mode = states('input_select.topny_rezim') %}
{% set active = state_attr('sensor.heating_schedule_windows', 'active_helpers') or [] %}
{% for z in ["sklep_michal","prizemi_michal","prizemi_chodba_zachod","1p_jidelna","1p_kuchyn","1p_koupelna","1p_chodba","2p_mama"] %}
{% set comfort = states('input_number.' ~ z ~ '_last_comfort') | float(default=none) %}
{% set enabled = is_state('input_boolean.schedule_enable_' ~ z, 'on') %}
{% set manual = is_state('input_boolean.' ~ z ~ '_manual_override', 'on') and (is_state('input_select.' ~ z ~ '_manual_override_type', 'Do další změny rozvrhu') or (is_state('input_select.' ~ z ~ '_manual_override_type', 'Časovač') and is_state('timer.' ~ z ~ '_manual_override', 'active'))) %}
{% set in_window = 'input_boolean.' ~ z ~ '_schedule_active' in active %}
{% set boost = is_state('binary_sensor.kotel_boost_active', 'on') %}
{% set value = eco if not enabled else comfort if manual else comfort + (states('input_number.boost_comfort_offset_c') | float(0)) if boost and comfort is not none else eco if mode in ['Eco', 'Vypnuto', 'Off'] else comfort if in_window else eco %}
{% set low = state_attr('climate.' ~ z, 'min_temp') | float(5) %}
{% set high = state_attr('climate.' ~ z, 'max_temp') | float(29) %}
{% set ns.values = dict(ns.values, **{z: ([[value, low] | max, high] | min if value is not none else none)}) %}
{% endfor %}
{{ ns.values }}

if.value_template:
{% set ns=namespace(ok=true) %}
{% for z in ['sklep_michal','prizemi_michal','prizemi_chodba_zachod','1p_jidelna','1p_kuchyn','1p_koupelna','1p_chodba','2p_mama'] %}
  {% set target = targets[z] %}
  {% set actual = state_attr('climate.' ~ z, 'temperature') %}
  {% if target is not number or actual is not number or ((actual|float)-(target|float))|abs >= 0.1 %}
    {% set ns.ok=false %}
  {% endif %}
{% endfor %}
{{ ns.ok }}

options.state:
{% set p=states('input_text.heating_restart_shadow_v1')[3:]|from_json([]) %}
{% set ns=namespace(c=0,ok=true) %}
{% for e in ['climate.sklep_michal','climate.prizemi_michal','climate.prizemi_chodba_zachod','climate.1p_jidelna','climate.1p_kuchyn','climate.1p_koupelna','climate.1p_chodba','climate.2p_mama'] %}
  {% set pi=state_attr(e,'pi_heating_demand') %}
  {% if states(e) not in ['heat','off'] or not is_number(pi) %}
    {% set ns.ok=false %}
  {% elif states(e)=='heat' and pi|float >= 20 %}
    {% set ns.c=ns.c+1 %}
  {% endif %}
{% endfor %}
{{ p|length==9
   and as_timestamp(now())-(p[5]|float(0)) < 45
   and p[1]==1 and p[2]==0 and p[3]>=1
   and ns.ok and ns.c<2
   and is_state('input_boolean.topny_system_enable','on')
   and is_state('input_boolean.heating_service_mode','off')
   and is_state('switch.kotel_rele_spinac','on')
   and is_state('binary_sensor.boiler_burngas','off')
   and is_state('sensor.system_bus_status','connected')
   and states('sensor.boiler_servicecodenumber') not in ['2964','2965','2966','2967'] }}

{% set raw=states('input_text.heating_flow_relief_state_v1') %}
{% set x=raw[3:]|from_json([]) if raw.startswith('v3:') else [] %}
{% set ns=namespace(n=0) %}
{% if x|length==3 and x[2]|length==8 and is_state('input_boolean.heating_flow_relief_mode','on') %}
  {% set zones=[
    ['climate.sklep_michal','sensor.sklep_michal_pocet_kroku_motoru',x[2][0]],
    ['climate.prizemi_michal','sensor.prizemi_michal_pocet_kroku_motoru',x[2][1]],
    ['climate.prizemi_chodba_zachod','sensor.prizemi_chodba_zachod_pocet_kroku_motoru',x[2][2]],
    ['climate.1p_jidelna','sensor.1p_jidelna_pocet_kroku_motoru',x[2][3]],
    ['climate.1p_kuchyn','sensor.1p_kuchyn_pocet_kroku_motoru',x[2][4]],
    ['climate.1p_koupelna','sensor.1p_koupelna_pocet_kroku_motoru',x[2][5]],
    ['climate.1p_chodba','sensor.1p_chodba_pocet_kroku_motoru',x[2][6]],
    ['climate.2p_mama','sensor.2p_mama_pocet_kroku_motoru',x[2][7]]
  ] %}
  {% for z in zones %}
    {% if is_number(state_attr(z[0],'temperature')) and (state_attr(z[0],'temperature')|float)>=28.9
       and is_number(states(z[1])) and (states(z[1])|float)>(z[2]|float) %}
      {% set ns.n=ns.n+1 %}
    {% endif %}
  {% endfor %}
{% endif %}
{{ ns.n >= 2 }}

